<template><VContainer class="setup"><VCard class="pa-8" max-width="620"><h1>Bienvenido a Xeler</h1><VAlert v-if="error" type="error" class="mb-4">{{error}}</VAlert><template v-if="ready"><p>Has sido invitado como: <strong>{{role}}</strong></p><VForm @submit.prevent="submit"><VTextField v-model="password" label="Definir contraseña" :type="show?'text':'password'" autocomplete="new-password" :append-inner-icon="show?'mdi-eye-off':'mdi-eye'" @click:append-inner="show=!show"/><PasswordRequirements :password="password"/><VTextField v-model="confirmation" label="Confirmar contraseña" :type="showConfirm?'text':'password'" autocomplete="new-password" :append-inner-icon="showConfirm?'mdi-eye-off':'mdi-eye'" @click:append-inner="showConfirm=!showConfirm"/><VBtn type="submit" color="primary" block>Activar mi cuenta</VBtn></VForm></template><VBtn v-if="done" to="/login" color="primary">Ir a iniciar sesión</VBtn></VCard></VContainer></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import PasswordRequirements from '@/components/PasswordRequirements.vue';import{setupApi}from'@/services/adminSetupApi';const route=useRoute(),token=String(route.params.token),role=ref(''),ready=ref(false),done=ref(false),error=ref(''),password=ref(''),confirmation=ref(''),show=ref(false),showConfirm=ref(false);onMounted(async()=>{try{const r=await setupApi.invitation(token);role.value=r.data.role;ready.value=true}catch(e:any){error.value=e.response?.data?.message||'La invitación no está disponible.'}});async function submit(){try{await setupApi.accept(token,{password:password.value,password_confirmation:confirmation.value});ready.value=false;done.value=true}catch(e:any){const fields=(e.response?.data?.errors||{}) as Record<string,string[]>;error.value=e.response?.data?.message||Object.values(fields)[0]?.[0]||'No fue posible activar la cuenta.'}}</script><style scoped>.setup{min-height:100vh;display:grid;place-items:center;background:#f3f6fb}h1{color:#16345f;margin-bottom:1rem}</style>
